// Move a character one square at a time, stopping at walls and waiting until each step is
// finished.
// grid-movement: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width,height,step_seconds,repeat_delay,repeat_interval,buffer_seconds,dt,direction,...9_
// state_values,...row_major_grid]
// Output: [...9_next_state_values,visual_x,visual_y,steps_started,tiles_arrived,blocked_flag]
// Persistent one-update controller. Directions 0=release,1=up,2=right,3=down,4=left (Y down).
// State: tile_x,tile_y,target_x,target_y,progress,buffered_direction,held_direction,repeat_remaini
// ng,buffer_remaining. Keep the first nine outputs for the next call. Zero tiles are walkable. dt
// is 0..1 seconds; repeat delay/interval >=0.01 seconds. See README for event ordering and static-
// map assumptions; [-1] means invalid configuration/state.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

// Count how many numbers are in this list.
function port_length(a: number[]): number { return a.length; }
// Read one number at a zero-based position; stop if that position does not exist.
function port_get(a: number[], i: number): number { if (!Number.isInteger(i) || i < 0 || i >= a.length) throw new RangeError("index"); return a[i]; }
// Choose the smaller of two numbers.
function port_minimum(a: number, b: number): number { return Math.min(a,b); }
// Choose the larger of two numbers.
function port_maximum(a: number, b: number): number { return Math.max(a,b); }
// Round down to a whole number; minus 0.1 becomes minus 1.
function port_floor_num(a: number): number { return Math.floor(a); }
// Remove a negative sign so a distance or size is not negative.
function port_abs_num(a: number): number { return Math.abs(a); }

// 1. Read one direction: up, right, down, left, or no button.
// 2. Check the next square. Stay put if it is outside the map or contains a wall.
// 3. Either jump straight to that square or slide to it over the chosen step time.
// 4. Remember the newest direction briefly if it is pressed during a step. Try it after landing.
// 5. Holding a direction waits for a short delay, then requests more steps at regular times.
// Releasing stops those repeats.
export function compute(data: number[]): number[] {
    let w: number = 0;
    let h: number = 0;
    let step_seconds: number = 0;
    let repeat_delay: number = 0;
    let repeat_interval: number = 0;
    let buffer_seconds: number = 0;
    let remaining: number = 0;
    let direction: number = 0;
    let tile_x: number = 0;
    let tile_y: number = 0;
    let target_x: number = 0;
    let target_y: number = 0;
    let progress: number = 0;
    let buffered: number = 0;
    let held: number = 0;
    let repeat_remaining: number = 0;
    let buffer_remaining: number = 0;
    let started: number = 0;
    let arrived: number = 0;
    let blocked: number = 0;
    let visual_x: number = 0;
    let visual_y: number = 0;
    let advance: number = 0;
    let nx: number = 0;
    let ny: number = 0;
    let passable: number = 0;
    if ((port_length(data) < 18)) {
        return [-(1)];
    }
    w = port_get(data, 0);
    h = port_get(data, 1);
    step_seconds = port_get(data, 2);
    repeat_delay = port_get(data, 3);
    repeat_interval = port_get(data, 4);
    buffer_seconds = port_get(data, 5);
    remaining = port_get(data, 6);
    direction = port_get(data, 7);
    tile_x = port_get(data, 8);
    tile_y = port_get(data, 9);
    target_x = port_get(data, 10);
    target_y = port_get(data, 11);
    progress = port_get(data, 12);
    buffered = port_get(data, 13);
    held = port_get(data, 14);
    repeat_remaining = port_get(data, 15);
    buffer_remaining = port_get(data, 16);
    if (((w < 1) || (h < 1) || (port_floor_num(w) != w) || (port_floor_num(h) != h) || (port_length(data) != (17 + (w * h))))) {
        return [-(1)];
    }
    if (((step_seconds < 0) || (repeat_delay < 0.01) || (repeat_interval < 0.01) || (buffer_seconds < 0) || (remaining < 0) || (remaining > 1))) {
        return [-(1)];
    }
    if (((direction < 0) || (direction > 4) || (port_floor_num(direction) != direction) || (held < 0) || (held > 4) || (port_floor_num(held) != held) || (buffered < 0) || (buffered > 4) || (port_floor_num(buffered) != buffered))) {
        return [-(1)];
    }
    if (((tile_x < 0) || (tile_x >= w) || (tile_y < 0) || (tile_y >= h) || (target_x < 0) || (target_x >= w) || (target_y < 0) || (target_y >= h))) {
        return [-(1)];
    }
    if (((port_floor_num(tile_x) != tile_x) || (port_floor_num(tile_y) != tile_y) || (port_floor_num(target_x) != target_x) || (port_floor_num(target_y) != target_y))) {
        return [-(1)];
    }
    if (((progress < 0) || (progress > 1) || (repeat_remaining < 0) || (buffer_remaining < 0) || ((port_abs_num((target_x - tile_x)) + port_abs_num((target_y - tile_y))) > 1))) {
        return [-(1)];
    }
    if ((((target_x == tile_x) && (target_y == tile_y) && (progress != 0)) || (port_get(data, ((17 + (tile_y * w)) + tile_x)) != 0) || (port_get(data, ((17 + (target_y * w)) + target_x)) != 0))) {
        return [-(1)];
    }
    // Instant mode cannot resume a previously unfinished smooth step.
    if (((step_seconds == 0) && ((target_x != tile_x) || (target_y != tile_y)))) {
        return [-(1)];
    }
    // A changed direction is a fresh press; a release stops repeating but keeps a live buffer.
    if ((direction != held)) {
        held = direction;
        repeat_remaining = 0;
        if ((direction != 0)) {
            repeat_remaining = repeat_delay;
            buffered = direction;
            buffer_remaining = buffer_seconds;
        }
    }
    started = 0;
    arrived = 0;
    blocked = 0;
    // Process exact event boundaries so a long update does not skip repeats or overshoot tiles.
    while ((1 == 1)) {
        if ((((target_x != tile_x) || (target_y != tile_y)) && (progress >= (1 - 1e-09)))) {
            tile_x = target_x;
            tile_y = target_y;
            progress = 0;
            arrived += 1;
        }
        if (((held != 0) && (repeat_remaining <= 1e-09))) {
            buffered = held;
            buffer_remaining = buffer_seconds;
            repeat_remaining += repeat_interval;
        }
        if (((tile_x == target_x) && (tile_y == target_y) && (buffered != 0))) {
            nx = tile_x;
            ny = tile_y;
            if ((buffered == 1)) {
                ny -= 1;
            }
            if ((buffered == 2)) {
                nx += 1;
            }
            if ((buffered == 3)) {
                ny += 1;
            }
            if ((buffered == 4)) {
                nx -= 1;
            }
            // Consume each request once, including a blocked request.
            buffered = 0;
            buffer_remaining = 0;
            passable = 0;
            if (((nx >= 0) && (nx < w) && (ny >= 0) && (ny < h))) {
                if ((port_get(data, ((17 + (ny * w)) + nx)) == 0)) {
                    passable = 1;
                }
            }
            if ((passable == 0)) {
                blocked = 1;
            } else {
                target_x = nx;
                target_y = ny;
                started += 1;
                if ((step_seconds == 0)) {
                    tile_x = target_x;
                    tile_y = target_y;
                    arrived += 1;
                }
            }
        }
        if ((remaining <= 1e-09)) {
            break;
        }
        advance = remaining;
        if ((held != 0)) {
            advance = port_minimum(advance, repeat_remaining);
        }
        if (((tile_x != target_x) || (tile_y != target_y))) {
            advance = port_minimum(advance, ((1 - progress) * step_seconds));
            progress += (advance / step_seconds);
        }
        remaining = port_maximum(0, (remaining - advance));
        if ((held != 0)) {
            repeat_remaining = port_maximum(0, (repeat_remaining - advance));
        }
        if ((buffered != 0)) {
            buffer_remaining -= advance;
            // A buffer remains valid at its exact deadline, but expires strictly after it.
            if ((buffer_remaining < -(1e-09))) {
                buffered = 0;
                buffer_remaining = 0;
            } else {
                buffer_remaining = port_maximum(0, buffer_remaining);
            }
        }
    }
    visual_x = (tile_x + ((target_x - tile_x) * progress));
    visual_y = (tile_y + ((target_y - tile_y) * progress));
    return [tile_x, tile_y, target_x, target_y, progress, buffered, held, repeat_remaining, buffer_remaining, visual_x, visual_y, started, arrived, blocked];
}
